def choose_move(observation):
    def _pos(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return default

    def _step(a, b):
        dx = 0 if b[0] == a[0] else (1 if b[0] > a[0] else -1)
        dy = 0 if b[1] == a[1] else (1 if b[1] > a[1] else -1)
        return [dx, dy]

    def _manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def _best_target(start, items, opp=None, contest=False):
        best = None
        best_score = None
        for item in items or []:
            p = _pos(item, None)
            if p is None:
                continue
            ds = _manhattan(start, p)
            if opp is None:
                score = ds
            else:
                do = _manhattan(opp, p)
                score = ds * 2 - do if contest else ds * 2 - do
            if best_score is None or score < best_score or (score == best_score and ds < _manhattan(start, best)):
                best_score = score
                best = p
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = _pos(observation.get("self_position", (0, 0)))
    ox, oy = _pos(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return _step(self_pos, opp_pos)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if corners:
            target = max(corners, key=lambda c: _manhattan(c, opp_pos))
            return _step(self_pos, target)
        return _step(opp_pos, self_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = _best_target(self_pos, targets, opp_pos, contest=True)
        if target is not None:
            return _step(self_pos, target)
        own = observation.get("own_territory") or observation.get("claimed_cells") or []
        if own:
            target = _best_target(self_pos, own, opp_pos, contest=False)
            if target is not None:
                return _step(self_pos, target)
        return _step(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = _best_target(self_pos, resources, opp_pos, contest=True)
    if target is not None:
        return _step(self_pos, target)

    if opp_pos != self_pos:
        return _step(opp_pos, self_pos)

    return [0, 0]

